select n.nspname as schema_name,p.proname,pg_get_functiondef(p.oid) as definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('jra_live_locked_2025_score_packet_v1','jra_segmented_diagnosis_score') union all select n.nspname,c.relname,case when c.relkind in ('v','m') then pg_get_viewdef(c.oid,true) else 'RELKIND='||c.relkind::text end from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('jra_live_rank_entries','jra_live_diagnosis_entries');
